import struct, zlib
def pack(ver, ecu, state, pct):
    body = struct.pack(">BHBB", ver, ecu, state, pct)
    return body + struct.pack(">I", zlib.crc32(body))
def unpack(b):
    body, crc = b[:-4], struct.unpack(">I", b[-4:])[0]
    if zlib.crc32(body) != crc:
        return "CRC 틀림 — 버린다"
    return struct.unpack(">BHBB", body)
m = pack(1, 0x0710, 2, 40)
print(m.hex(), len(m), "바이트 ->", unpack(m))
bad = m[:4] + bytes([41]) + m[5:]
print("진행률 한 바이트 바뀜 ->", unpack(bad))

car = {"HPVC": "2.3.0", "ZONE-F": "1.4.2", "ZONE-R": "1.4.2", "BCM": "5.0.1"}
campaign = {"HPVC": ("2.4.0", {"ZONE-F": ">=1.5.0"}), "ZONE-F": ("1.5.0", {}), "BCM": ("5.0.2", {})}
def ge(a, b):
    return tuple(map(int, a.split("."))) >= tuple(map(int, b.split(".")))
after = dict(car)
for ecu, (v, _) in campaign.items():
    after[ecu] = v
for ecu, (v, deps) in campaign.items():
    for d, cond in deps.items():
        ok = ge(after[d], cond[2:])
        print(f"{ecu} {v} 는 {d} {cond} 필요 -> 설치 뒤 {after[d]}: {'OK' if ok else '깨짐'}")
failed = dict(after); failed["ZONE-F"] = car["ZONE-F"]
print("ZONE-F 만 실패하면 HPVC 조건:", "OK" if ge(failed["ZONE-F"], "1.5.0") else "깨짐 -> 묶음 전체를 되돌리거나 HPVC 활성화를 막는다")
